export const subServiceMdListings = subServicesMd.map(({ slug, categorySlug, title, serviceName, metaTitle, metaDescription }) => ({ slug, categorySlug, title, serviceName, metaTitle, metaDescription }));

export function getSubServiceMdBySlug(slug) {
  return subServicesMd.find((s) => s.slug === slug) || null;
}

export function getSubServiceMdByCategoryAndSlug(category, slug) {
  return subServicesMd.find((s) => s.categorySlug === category && s.slug === slug) || getSubServiceMdBySlug(slug);
}
